import { WebSocketServer, WebSocket } from 'ws';
import express from 'express';
import http from 'http';
import cors from 'cors';
import crypto from 'crypto';
import { StandardChessRuleset, FogOfWarRuleset, SpellChessRuleset } from '@chaturanga/shared';
const port = 11429;
const app = express();
app.use(cors());
const server = http.createServer(app);
const wss = new WebSocketServer({ server });
const rooms = new Map(); // roomId -> GameSession
const clients = new Map(); // sessionId -> WebSocket
const clientRooms = new Map(); // sessionId -> roomId
function getRulesetForVariant(variant) {
    if (variant === 'fog')
        return new FogOfWarRuleset();
    if (variant === 'spell')
        return new SpellChessRuleset();
    return new StandardChessRuleset();
}
function broadcastToRoom(roomId) {
    const room = rooms.get(roomId);
    if (!room || !room.gameState)
        return;
    // Find all clients in this room
    for (const [sessionId, connectedRoomId] of clientRooms.entries()) {
        if (connectedRoomId === roomId) {
            const ws = clients.get(sessionId);
            if (ws && ws.readyState === WebSocket.OPEN) {
                const color = room.players.w === sessionId ? 'w' : room.players.b === sessionId ? 'b' : 'w'; // spectator defaults to w view
                const playerView = room.ruleset.getPlayerView(room.gameState, color);
                ws.send(JSON.stringify({ type: 'state', state: playerView }));
            }
        }
    }
}
wss.on('connection', (ws) => {
    const sessionId = crypto.randomUUID();
    clients.set(sessionId, ws);
    console.log(`[Server] Player connected: ${sessionId}`);
    ws.on('message', (data) => {
        try {
            const message = JSON.parse(data.toString());
            if (message.type === 'join') {
                const variant = message.variant || 'classic'; // 'classic', 'fog', 'spell', '4p'
                // Find a waiting room for this variant, or create one
                let joinedRoomId = null;
                for (const [roomId, room] of rooms.entries()) {
                    if (room.variant === variant && (!room.players.w || !room.players.b)) {
                        joinedRoomId = roomId;
                        break;
                    }
                }
                if (!joinedRoomId) {
                    joinedRoomId = crypto.randomUUID();
                    rooms.set(joinedRoomId, {
                        id: joinedRoomId,
                        variant,
                        ruleset: getRulesetForVariant(variant),
                        gameState: null,
                        players: {},
                        spectators: []
                    });
                    console.log(`[Server] Created new room ${joinedRoomId} for variant ${variant}`);
                }
                clientRooms.set(sessionId, joinedRoomId);
                const room = rooms.get(joinedRoomId);
                // Assign color
                if (!room.players.w) {
                    room.players.w = sessionId;
                    ws.send(JSON.stringify({ type: 'seat', color: 'w' }));
                }
                else if (!room.players.b) {
                    room.players.b = sessionId;
                    ws.send(JSON.stringify({ type: 'seat', color: 'b' }));
                }
                else {
                    room.spectators.push(sessionId);
                    ws.send(JSON.stringify({ type: 'seat', color: 'spectator' }));
                }
                // Check if ready to start
                if (room.players.w && room.players.b && !room.gameState) {
                    room.gameState = room.ruleset.getInitialState({ w: room.players.w, b: room.players.b });
                    broadcastToRoom(joinedRoomId);
                }
                else if (room.gameState) {
                    // Reconnect / Late spectator
                    const color = room.players.w === sessionId ? 'w' : room.players.b === sessionId ? 'b' : 'w';
                    ws.send(JSON.stringify({ type: 'state', state: room.ruleset.getPlayerView(room.gameState, color) }));
                }
                return;
            }
            if (message.type === 'command') {
                const roomId = clientRooms.get(sessionId);
                if (!roomId)
                    return;
                const room = rooms.get(roomId);
                if (!room || !room.gameState)
                    return;
                const cmd = message.command;
                const color = room.players.w === sessionId ? 'w' : room.players.b === sessionId ? 'b' : null;
                if (color !== cmd.playerColor) {
                    ws.send(JSON.stringify({ type: 'error', message: 'Not your turn or spectator' }));
                    return;
                }
                const result = room.ruleset.applyCommand(room.gameState, cmd);
                if (result.error) {
                    ws.send(JSON.stringify({ type: 'error', message: result.error }));
                    return;
                }
                room.gameState = result.newState;
                broadcastToRoom(roomId);
            }
        }
        catch (e) {
            console.error('Invalid message', e);
        }
    });
    ws.on('close', () => {
        const roomId = clientRooms.get(sessionId);
        if (roomId) {
            const room = rooms.get(roomId);
            if (room) {
                if (room.players.w === sessionId)
                    delete room.players.w;
                if (room.players.b === sessionId)
                    delete room.players.b;
            }
            clientRooms.delete(sessionId);
        }
        clients.delete(sessionId);
        console.log(`[Server] Player disconnected: ${sessionId}`);
    });
});
server.listen(port, () => {
    console.log(`[Chaturanga Server] Multi-room Lobby running on ws://localhost:${port}`);
});
